import ast,json,argparse,hashlib
from pathlib import Path
import numpy as np
np.seterr(over='raise',invalid='raise',divide='raise',under='ignore')
p=argparse.ArgumentParser();p.add_argument('--pairs',nargs='+',required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();helper=Path(__file__).with_name('check_constraint_incoming_lift.py');tree=ast.parse(helper.read_text());exec(compile(ast.Module(body=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name in ['mm','symbols']],type_ignores=[]),str(helper),'exec'));records=[];hashes={}
for pair in a.pairs:
 sp,sa=map(Path,pair.split('::'));samples=np.loadtxt(sa);hashes[str(sp)]=hashlib.sha256(sp.read_bytes()).hexdigest();hashes[str(sa)]=hashlib.sha256(sa.read_bytes()).hexdigest()
 for j,s in enumerate(symbols(sp)):
  fields=samples[j,7:32];alpha,chi=fields[18],fields[0];beta=fields[19:22];n=s['normal'];ginv=s['inverse'];v=np.einsum('ij,j->i',ginv,n);G=float(np.dot(n,v));b=float(np.dot(beta,n));om=s['omega'];d=om*alpha*chi;C=s['constraints'];M=s['matrix'];B=b*np.eye(8);B[0,1:4]=-2*d*v;B[1:4,0]=-alpha*n/(2*om);B[1:4,5:8]=d*(G*np.eye(3)-np.outer(n,v));B[4,0]=alpha/(2*om);B[4,5:8]=d*v;B[5:8,1:4]=alpha/om*np.eye(3);B[5:8,4]=alpha/om*n
  predicted=mm(B,C);native=mm(C,M);res=float(np.linalg.norm(native-predicted)/max(1.,np.linalg.norm(native),np.linalg.norm(predicted)));scale=np.linalg.norm(C,axis=1);Cn=C/scale[:,None];rank=int(np.linalg.matrix_rank(Cn,tol=1e-10));uc,sc,vc=np.linalg.svd(C,full_matrices=False);rightinverse=mm(vc.T/sc[None,:],uc.T);quotient=mm(mm(C,M),rightinverse);quotientdef=float(np.linalg.norm(B-quotient)/max(1.,np.linalg.norm(B)));c=alpha*np.sqrt(chi*G);wave=mm(B-b*np.eye(8),B-b*np.eye(8))-c*c*np.eye(8);waveerr=float(np.linalg.norm(wave)/max(1.,np.linalg.norm(B)**2));S=-B;lo,hi=-b-c,-b+c;Pin=(hi*np.eye(8)-S)/(hi-lo);Pout=np.eye(8)-Pin;H=mm(Pin.T,Pin)+mm(Pout.T,Pout);flux=mm(H,S);symdef=float(np.linalg.norm(flux-flux.T)/max(1.,np.linalg.norm(flux)));hs=np.linalg.eigvalsh(H);ev=np.linalg.eigvals(S);speederror=float(max(abs(np.sort(ev.real)-np.array([lo]*4+[hi]*4))));negative=B.copy();negative[1:4,5:8]=0;neg=float(np.linalg.norm(native-mm(negative,C))/max(1.,np.linalg.norm(native)));passed=rank==8 and res<=1e-10 and quotientdef<=1e-10 and waveerr<=1e-10 and symdef<=1e-10 and hs[0]>0 and speederror<=1e-9*max(1,abs(lo),abs(hi)) and max(abs(ev.imag))<=1e-9
  R=B[4:,:]+hi*np.eye(8)[4:,:];nativeR=mm(C[4:,:],M+hi*np.eye(20));rowdef=float(np.linalg.norm(mm(R,C)-nativeR)/max(1.,np.linalg.norm(nativeR)));outleak=float(np.linalg.norm(mm(R,Pout))/max(1.,np.linalg.norm(R)));incomingrank=int(np.linalg.matrix_rank(mm(R,Pin),tol=1e-10));passed=passed and rowdef<=1e-10 and outleak<=1e-10 and incomingrank==4
  records.append(dict(boundary_rows=R.tolist(),boundary_row_crosscheck=rowdef,boundary_outgoing_leak=outleak,boundary_incoming_rank=incomingrank,source=str(sp),sample=j,alpha=float(alpha),chi=float(chi),Omega=om,beta_normal=b,normal=n.tolist(),subsidiary_matrix=B.tolist(),constraint_rank=rank,intertwining_relative_residual=res,quotient_relative_difference=quotientdef,wave_polynomial_relative_residual=waveerr,speeds=np.sort(ev.real).tolist(),speed_error=speederror,symmetrizer_min=float(hs[0]),symmetrizer_condition=float(hs[-1]/hs[0]),symmetric_flux_residual=symdef,omitted_transverse_coupling_relative_residual=neg,passed=bool(passed)))
r=dict(passed=all(x['passed'] for x in records),records=records,input_hashes=hashes,source_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),scope='Explicit frozen native H/M/normalTheta/normalZ principal system only, not finiteOmega lower-order closure or weakSAT');a.output.write_text(json.dumps(r,indent=2)+'\n');print('PASS',r['passed'],'states',len(records),'maxclosure',max(x['intertwining_relative_residual'] for x in records),'negative',max(x['omitted_transverse_coupling_relative_residual'] for x in records))
